import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"拓扑排序","description":"","frontmatter":{"title":"拓扑排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/topo-sort.md","filePath":"cs/topo-sort.md","lastUpdated":1789023840000}'),c={name:"cs/topo-sort.md"};function u(E,a,A,_,D,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="拓扑排序" tabindex="-1">拓扑排序 <a class="header-anchor" href="#拓扑排序" aria-label="Permalink to &quot;拓扑排序&quot;">​</a></h1><div class="epigraph"><p>无环有向图的顶点可以排成一线，使得每条边都从左指向右。</p><footer>—— 据 Kahn, Topological Sorting of Large Networks, 1962；CLRS 第 22.4 节整理</footer></div><p>上一课<a href="/cs/bcc-bridge">连通分量与桥</a>证明：有向环当且仅当有反向边。<a href="/cs/dag-repr">DAG 与拓扑序预备</a>已说明无环才能线性化。本课不重证无环。缺口是：<strong>算法</strong>——给出一个合法顶点序，或报告不可能。本课只交出按完成时刻降序，以及 Kahn 的入度为零队列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任务依赖、编译的符号、包安装，边 \\(u\\to v\\) 表示 \\(u\\) 先于 \\(v\\)。需要一条总序尊重全部边。有环则不存在。缺口不是再定义 DAG，而是从邻接表在 \\(\\Theta(V+E)\\) 内产出序。</p><p>DFS 法：做一遍 DFS，按 \\(u.f\\) 降序输出。正确性：若有边 \\(u\\to v\\)，则 \\(v.f\\lt u.f\\)（否则 \\(u\\to v\\) 会是反向边，与 DAG 矛盾）。Kahn：反复取入度 \\(0\\) 的点，删出边；若结束时还有点，则有环。</p><h3 id="拓扑序不是唯一的最短路" tabindex="-1">拓扑序不是唯一的最短路 <a class="header-anchor" href="#拓扑序不是唯一的最短路" aria-label="Permalink to &quot;拓扑序不是唯一的最短路&quot;">​</a></h3><p>同一 DAG 可以有许多拓扑序。BFS 层序不是拓扑序，除非图碰巧是按层编号的。也不要把拓扑序当成加权最短路：那是后课在 DAG 上按拓扑松弛，本课只给序。</p><p><span class="marginnote">Kahn 1962 用入度；CLRS 用 DFS 完成时刻。两者等价于「存在且仅当无环」。并查集课已有的结构这里用不上：环检测走 DFS 或入度，不走连通分量的误用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任选其一。DFS 完成后倒序写表。Kahn 用<a href="/cs/queue-buffer">队列</a>存当前零入度点。输出长度小于 \\(|V|\\) 则失败。</p>',11)),(e(),n(d,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%9C%89%E5%90%91%E5%9B%BE%22%5D%20--%3E%20DFS%5B%22DFS%20%E5%AE%8C%E6%88%90%E6%97%B6%E5%88%BB%E9%99%8D%E5%BA%8F%22%5D%0A%20%20G%20--%3E%20KAHN%5B%22%E5%8F%8D%E5%A4%8D%E5%8F%96%E5%85%A5%E5%BA%A6%200%22%5D%0A%20%20DFS%20--%3E%20ORD%5B%22%E6%8B%93%E6%89%91%E5%BA%8F%E6%88%96%E6%8A%A5%E7%8E%AF%22%5D%0A%20%20KAHN%20--%3E%20ORD%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/sparse-graph">稀疏图</a>用邻接表；每次边只降一次入度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>序一旦给出，后课可按序做动态规划或松弛：到 \\(v\\) 时全部前驱已处理。这是 DAG 最短路、最长路的共同前置，本课不把松弛写进来。编译课的依赖仍是同一对象：通行证之间的边若成环则无法排程。</p><p>多个零入度点时 Kahn 的队列次序决定哪一个合法序；那是平局，不是错误。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理带权边。不写强连通分量缩点后再拓扑——那是把有环图缩成 DAG 的后话。无向图没有拓扑序这一定义。偏序的线性扩张在组合里更一般，本课只做有向图上的算法。</p><p>后课默认：DAG 上有 \\(\\Theta(V+E)\\) 拓扑序；有环则算法报告失败。正权最短路下一课从另一端（非负权一般图）进入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAG 上拓扑序存在；DFS 完成降序或 Kahn 入度均可。</li><li>有向环则失败；代价 \\(\\Theta(V+E)\\)。</li><li>序不唯一；本课不给最短路。</li><li>出处：Kahn, 1962；CLRS 第 22.4 节。</li></ul>',9))])}const T=s(c,[["render",u]]);export{S as __pageData,T as default};
